// Scan the I2C bus, then read the MPU-6050's WHO_AM_I register.
#include <Wire.h>

const byte MPU_ADDR = 0x68;   // AD0 low: 0x68
const byte WHO_AM_I = 0x75;

void setup() {
  pinMode(LED_BUILTIN, OUTPUT);
  Serial.begin(9600);
  Wire.begin();               // A4 = SDA, A5 = SCL
  byte found = 0;
  for (byte addr = 1; addr < 127; addr++) {
    Wire.beginTransmission(addr);
    if (Wire.endTransmission() == 0) {
      Serial.print("Found device at 0x");
      Serial.println(addr, HEX);
      found++;
    }
  }
  Serial.print("Devices: ");
  Serial.println(found);

  Wire.beginTransmission(MPU_ADDR);
  Wire.write(WHO_AM_I);
  Wire.endTransmission(false);  // keep the bus: repeated start
  Wire.requestFrom(MPU_ADDR, (byte)1);
  if (Wire.available()) {
    Serial.print("WHO_AM_I = 0x");
    Serial.println(Wire.read(), HEX);
  }
}

void loop() {
  digitalWrite(LED_BUILTIN, HIGH);  // heartbeat on L
  delay({{p:blink}});
  digitalWrite(LED_BUILTIN, LOW);
  delay({{p:blink}});
}

